def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    from collections import defaultdict

    # Parse grid values into a dictionary for quick access
    grid = defaultdict(int)
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[(x-1, y-1)] = value

    # Initialize a 3D DP array
    dp = [[[-float('inf')] * N for _ in range(N)] for _ in range(N*N + 1)]
    dp[0][0][0] = grid[(0, 0)]

    for step in range(1, 2*N - 1):
        for i in range(max(0, step - (N-1)), min(N, step + 1)):
            for j in range(max(0, step - (N-1)), min(N, step + 1)):
                if i == 0 and j == 0:
                    continue
                x1, y1 = step - i, i
                x2, y2 = step - j, j
                if not (0 <= x1 < N and 0 <= y1 < N and 0 <= x2 < N and 0 <= y2 < N):
                    continue
                value = grid[(x1, y1)] if (x1, y1) == (x2, y2) else grid[(x1, y1)] + grid[(x2, y2)]
                candidates = []
                if i > 0 and j > 0:
                    candidates.append(dp[step-1][i-1][j-1])
                if i > 0:
                    candidates.append(dp[step-1][i-1][j])
                if j > 0:
                    candidates.append(dp[step-1][i][j-1])
                if candidates:
                    dp[step][i][j] = max(candidates) + value

    return dp[2*N-2][N-1][N-1] if dp[2*N-2][N-1][N-1] != -float('inf') else 0

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize the grid with zeros
    grid = [[0] * N for _ in range(N)]

    # Populate the grid with the given values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # Initialize the DP table
    dp = [[[-float('inf')] * N for _ in range(N)] for _ in range(2*N-1)]

    # Base case: starting point
    dp[0][0][0] = grid[0][0]

    # Fill the DP table
    for move in range(1, 2*N-1):
        for i in range(max(0, move-(N-1)), min(move+1, N)):
            for j in range(max(0, move-(N-1)), min(move+1, N)):
                if grid[i][move-i] == 0 or grid[j][move-j] == 0:
                    continue
                value = grid[i][move-i]
                if i != j:
                    value += grid[j][move-j]

                max_prev = -float('inf')
                for di, dj in [(-1, -1), (-1, 0), (0, -1), (-1, -1)]:
                    pi, pj = i+di, j+dj
                    if 0 <= pi < N and 0 <= pj < N:
                        max_prev = max(max_prev, dp[move-1][pi][pj])

                dp[move][i][j] = max(dp[move][i][j], max_prev + value)

    # The result is the maximum value in the last possible step
    return max(max(row) for row in dp[2*N-2]) if 2*N-2 < len(dp) else 0

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    import sys
    from typing import List, Tuple

    # Initialize the grid with zeros
    grid = [[0] * N for _ in range(N)]

    # Fill the grid with the given values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # Initialize the DP table with -inf
    dp = [[[-sys.maxsize] * N for _ in range(N)] for _ in range(N)]

    # Base case
    dp[0][0][0] = grid[0][0]

    # Fill the DP table
    for i in range(N):
        for j in range(N):
            for k in range(max(0, i+j-N+1), min(i+j+1, N)):
                l = i + j - k
                if i >= 1 and k >= 1:
                    dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k-1] + grid[i][j] + grid[k][l])
                if i >= 1:
                    dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k] + grid[i][j])
                    if l >= 1:
                        dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k] + grid[i][j] + grid[k][l-1])
                if k >= 1:
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j][k-1] + grid[k][l])
                    if j >= 1:
                        dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k-1] + grid[j][k] + grid[k][l])
                if j >= 1:
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k] + grid[j][k])
                    if k >= 1:
                        dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k] + grid[j][k] + grid[k-1][l])

    # Adjust for the case where both paths pick the same cell at the end
    if dp[N-1][N-1][N-1] == grid[N-1][N-1] * 2:
        dp[N-1][N-1][N-1] -= grid[N-1][N-1]

    return max(dp[N-1][N-1][N-1], 0)

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize the grid with zeros
    grid = [[0] * N for _ in range(N)]

    # Fill the grid with values from grid_values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # Initialize the DP table
    dp = [[[-float('inf')] * N for _ in range(N)] for _ in range(N * 2 - 1)]
    dp[0][0][0] = grid[0][0]

    # Fill the DP table
    for t in range(1, N * 2 - 1):
        for i in range(max(0, t + 1 - N), min(N, t + 1)):
            for j in range(max(0, t + 1 - N), min(N, t + 1)):
                if grid[i][t - i] == 0 or grid[j][t - j] == 0:
                    continue
                val = grid[i][t - i] + (grid[j][t - j] if i != j else 0)
                dp[t][i][j] = max(
                    dp[t][i][j],
                    dp[t-1][i-1][j] + val if i > 0 else -float('inf'),
                    dp[t-1][i][j-1] + val if j > 0 else -float('inf'),
                    dp[t-1][i-1][j-1] + val if i > 0 and j > 0 else -float('inf'),
                    dp[t-1][i][j] + val
                )

    return max(max(row) for row in dp[N * 2 - 2]) if dp[N * 2 - 2] else 0

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    import numpy as np

    # Create an N x N grid initialized with zeros
    grid = np.zeros((N, N), dtype=int)

    # Fill the grid with the given values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1, y-1] = value

    # Create a 3D DP table to store the maximum values collected
    dp = np.full((N, N, N, N), -np.inf)
    dp[0, 0, 0, 0] = grid[0, 0]

    # Fill the DP table
    for i1 in range(N):
        for j1 in range(N):
            for i2 in range(N):
                for j2 in range(N):
                    if i1 == 0 and j1 == 0 and i2 == 0 and j2 == 0:
                        continue
                    if i1 >= N or j1 >= N or i2 >= N or j2 >= N:
                        continue

                    max_value = -np.inf
                    if i1 > 0 and i2 > 0:
                        max_value = max(max_value, dp[i1-1, j1, i2-1, j2])
                    if i1 > 0 and j2 > 0:
                        max_value = max(max_value, dp[i1-1, j1, i2, j2-1])
                    if j1 > 0 and i2 > 0:
                        max_value = max(max_value, dp[i1, j1-1, i2-1, j2])
                    if j1 > 0 and j2 > 0:
                        max_value = max(max_value, dp[i1, j1-1, i2, j2-1])

                    if max_value == -np.inf:
                        continue

                    if i1 == i2 and j1 == j2:
                        dp[i1, j1, i2, j2] = max_value + grid[i1, j1]
                    else:
                        dp[i1, j1, i2, j2] = max_value + grid[i1, j1] + grid[i2, j2]

    return max(0, dp[N-1, N-1, N-1, N-1])

