    level = 1
    count = 0

    while count < N:
        count += level
        level += 1

    offset = N - (count - level) - 1
    if level % 2 == 0:
        numerator = offset + 1
        denominator = level - offset
    else:
        numerator = level - offset
        denominator = offset + 1

    return f"{numerator}/{denominator}"

def cantor_numbering(N: int) -> str:
    if N <= 0:
        raise ValueError("N must be a positive integer")

    diagonal = 0
    while N > 0:
        diagonal += 1
        N -= diagonal

    if diagonal % 2 == 0:
        # Even diagonals go from bottom-left to top-right
        numerator = 1 - N
        denominator = diagonal + N - 1
    else:
        # Odd diagonals go from top-right to bottom-left
        numerator = diagonal + N - 1
        denominator = 1 - N

    return f"{numerator}/{denominator}"

