def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn_parts):
        total = 0
        for i, digit in enumerate(isbn_parts):
            total += (i + 1) * int(digit)
        checksum = total % 11
        return 'X' if checksum == 10 else str(checksum)

    try:
        # Remove hyphens and check if the length is correct
        isbn_clean = isbn.replace('-', '')
        if len(isbn_clean) != 10:
            raise ValueError("ISBN must be 10 characters long without hyphens")

        # Extract the provided checksum
        provided_checksum = isbn_clean[-1]
        isbn_digits = isbn_clean[:-1]

        # Calculate the correct checksum
        correct_checksum = calculate_checksum(isbn_digits)

        # Compare the provided checksum with the correct checksum
        if provided_checksum == correct_checksum:
            return "Right"
        else:
            # Correct the ISBN by replacing the last character with the correct checksum
            corrected_isbn = isbn[:-1] + correct_checksum
            return corrected_isbn

    except (ValueError, IndexError) as e:
        return f"Invalid ISBN: {str(e)}"

def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> str:
        # Remove hyphens and convert to list of characters
        chars = [c for c in isbn if c != '-']
        total = 0
        for i in range(9):
            total += int(chars[i]) * (10 - i)
        checksum = 11 - (total % 11)
        return 'X' if checksum == 10 else str(checksum % 11)

    try:
        # Validate format
        if len(isbn) != 13 or isbn[1] != '-' or isbn[5] != '-' or isbn[11] != '-':
            raise ValueError("Invalid ISBN format")

        # Calculate expected checksum
        expected_checksum = calculate_checksum(isbn)

        # Get actual checksum
        actual_checksum = isbn[-1]

        # Compare checksums
        if actual_checksum == expected_checksum:
            return "Right"
        else:
            # Correct the ISBN with the right checksum
            corrected_isbn = isbn[:-1] + expected_checksum
            return corrected_isbn

    except Exception as e:
        raise ValueError(f"Error verifying ISBN: {e}")

