    vertical_aisles = [0] * (N + 1)

    for x1, y1, x2, y2 in chatting_pairs:
        if not (1 <= x1 <= M and 1 <= y1 <= N and 1 <= x2 <= M and 1 <= y2 <= N):
            raise ValueError("Chatting pair positions are out of bounds.")

        if x1 == x2:
            if y1 < y2:
                vertical_aisles[y1] += 1
                vertical_aisles[y2] -= 1
            else:
                vertical_aisles[y2] += 1
                vertical_aisles[y1] -= 1
        elif y1 == y2:
            if x1 < x2:
                horizontal_aisles[x1] += 1
                horizontal_aisles[x2] -= 1
            else:
                horizontal_aisles[x2] += 1
                horizontal_aisles[x1] -= 1
        else:
            raise ValueError("Chatting pairs must be in the same row or column.")

    for i in range(1, len(horizontal_aisles)):
        horizontal_aisles[i] += horizontal_aisles[i - 1]

