def count_passing_ways(n: int, m: int) -> int:
    if n <= 0 or m < 0:
        raise ValueError("Number of students must be greater than 0 and number of passes must be non-negative.")
    if n == 1:
        return 1 if m == 0 else 0

    # dp[i][j] will store the number of ways to reach student i after j passes
    dp = [[0] * (m + 1) for _ in range(n)]
    dp[0][0] = 1

    for passes in range(1, m + 1):
        for student in range(n):
            dp[student][passes] = dp[(student - 1) % n][passes - 1] + dp[(student + 1) % n][passes - 1]

    return dp[0][m]

