    # Initialize a set to keep track of cleared positions
    cleared_positions = set()

    for start, end in areas:
        if start < 0 or end < 0 or start > end or end > l:
            raise ValueError("Invalid area specified: start and end must be within the road length and start <= end.")

        # Add all positions in the range [start, end] to the cleared set
        cleared_positions.update(range(start, end + 1))

    # The number of remaining trees is the total length minus the number of cleared positions
    return l - len(cleared_positions)

def remaining_trees_after_clearing(l: int, areas: List[Tuple[int, int]]) -> int:
    if l <= 0:
        return 0

    cleared = set()
    for start, end in areas:
        if start < 0:
            start = 0
        if end >= l:
            end = l - 1
        for i in range(start, end + 1):
            cleared.add(i)

    return l - len(cleared)

def remaining_trees_after_clearing(l: int, areas: List[Tuple[int, int]]) -> int:
    if l < 0:
        raise ValueError("The length of the road cannot be negative.")
    if any(start < 0 or end < 0 or start > end for start, end in areas):
        raise ValueError("Invalid area range: start and end must be non-negative and start must be less than or equal to end.")

    cleared = [False] * l
    for start, end in areas:
        for i in range(max(0, start - 1), min(l, end)):
            cleared[i] = True

    return cleared.count(False)

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    if T < 0 or M < 0 or any(t < 0 or v < 0 for t, v in herbs):
        raise ValueError("Time, number of herbs, and herb values must be non-negative.")

    # Initialize a list to store the maximum value at each time up to T
    dp = [0] * (T + 1)

    # Iterate over each herb
    for t, v in herbs:
        # Update the dp array from back to front to avoid overwriting values needed for current iteration
        for i in range(T, t - 1, -1):
            dp[i] = max(dp[i], dp[i - t] + v)

    return dp[T]

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
