def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    if V < 0 or n < 0 or any(vol < 0 for vol in volumes):
        raise ValueError("Volume, number of items, and individual item volumes must be non-negative.")
    if n != len(volumes):
        raise ValueError("The number of items must match the length of the volumes list.")

    dp = [0] * (V + 1)

    for volume in volumes:
        for j in range(V, volume - 1, -1):
            dp[j] = max(dp[j], dp[j - volume] + volume)

    return V - dp[V]

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    if V < 0 or n < 0 or any(v < 0 for v in volumes):
        raise ValueError("All input values must be non-negative.")
    if n != len(volumes):
        raise ValueError("The number of items n must match the length of the volumes list.")

    # Initialize a DP array where dp[k] will be True if a subset with volume k can be formed
    dp = [False] * (V + 1)
    dp[0] = True  # A subset with volume 0 is always possible (empty subset)

    for volume in volumes:
        for k in range(V, volume - 1, -1):
            if dp[k - volume]:
                dp[k] = True

    # Find the maximum volume that can be packed into the box
    max_occupied_volume = max(k for k, can_fill in enumerate(dp) if can_fill)

    return V - max_occupied_volume

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    if V <= 0 or n <= 0 or not volumes:
        return V

    # Initialize a DP array where dp[i] represents whether a volume i can be achieved
    dp = [False] * (V + 1)
    dp[0] = True  # Base case: zero volume can always be achieved with no items

    try:
        for volume in volumes:
            for j in range(V, volume - 1, -1):
                if dp[j - volume]:
                    dp[j] = True
    except Exception as e:
        print(f"An error occurred: {e}")
        return V

    # Find the maximum volume that can be achieved which is less than or equal to V
    for j in range(V, -1, -1):
        if dp[j]:
            return V - j

    return V

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    try:
        if V < 0 or n < 0 or any(v < 0 for v in volumes):
            raise ValueError("Capacity, number of items, and volumes must be non-negative.")

        # Initialize a DP array where dp[i] will be True if a subset with volume i can be formed
        dp = [False] * (V + 1)
        dp[0] = True  # A subset with volume 0 is always possible (empty subset)

        # Update the DP array for each volume
        for v in volumes[:n]:
            for j in range(V, v - 1, -1):
                dp[j] = dp[j] or dp[j - v]

        # Find the maximum volume that can be formed which is less than or equal to V
        max_achievable_volume = max(i for i, can_form in enumerate(dp) if can_form)

        # The minimum remaining space is the total capacity minus the maximum achievable volume
        return V - max_achievable_volume

    except Exception as e:
        raise RuntimeError(f"An error occurred: {e}")

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(m + 1):
            dp[i][j] = dp[i - 1][j]
            for k in range(1, min(a[i - 1], j) + 1):
                dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD

    return dp[n][m]

